/* shape computation must mirror the generator's; see gen_a64_tab.py */
static const char *arr_desc(int w, int es)
{
    switch (w * 1000 + es) {
    case 64008: return "vec64.8";
    case 128008: return "vec128.8";
    case 64016: return "vec64.16";
    case 128016: return "vec128.16";
    case 64032: return "vec64.32";
    case 128032: return "vec128.32";
    case 64064: return "vec64.64";
    case 128064: return "vec128.64";
    case 128128: return "vec128.128";
    }
    return NULL;
}

#include <stdio.h>
int asma64_table(asm_ctx *c, const char *name, const char *base,
                 const char *sfx, a64opnd *o, int n,
                 uint8_t *out, size_t cap, size_t *outlen)
{
    char shape[96];
    size_t k = 0;
    (void)name; (void)sfx;
    shape[0] = 0;
    for (int i = 0; i < n && k < sizeof shape - 16; i++) {
        const char *d = "?";
        char buf[24];
        switch (o[i].t) {
        case A64_O_REG:
            if (o[i].kind == RK_X) d = "r64";
            else if (o[i].kind == RK_W) d = "r32";
            else if (o[i].kind == RK_S) d = "f32";
            else if (o[i].kind == RK_D) d = "f64";
            else if (o[i].kind == RK_Q) d = "f128";
            else if (o[i].kind == RK_B) d = "f8";
            else if (o[i].kind == RK_H) d = "f16";
            else if (o[i].kind == RK_V) {
                if (o[i].vidx >= 0 && o[i].vlanes == 0) {
                    snprintf(buf, sizeof buf, "vidx.%d", o[i].vbits);
                    d = buf;
                } else if (o[i].listcnt > 0) {
                    const char *a = arr_desc(o[i].vbits * o[i].vlanes, o[i].vbits);
                    if (!a) return -3;
                    snprintf(buf, sizeof buf, "list%d:%s", o[i].listcnt, a);
                    d = buf;
                } else {
                    const char *a = arr_desc(o[i].vbits * o[i].vlanes, o[i].vbits);
                    if (!a) return -3;
                    snprintf(buf, sizeof buf, "%s%s", a, o[i].vidx >= 0 ? "[i]" : "");
                    d = buf;
                }
            } else d = "f128";
            break;
        case A64_O_IMM: d = "imm"; break;
        case A64_O_MEM:
            if (o[i].idx_valid) d = "mem:idx";
            else if (o[i].wb_pre) d = "mem:pre";
            else if (o[i].wb_post) d = "mem:post";
            else d = "mem:plain";
            break;
        case A64_O_SFX:
            if (o[i].is_shift == 1 && o[i].amt_known &&
                (o[i].shx == SHK_LSL || o[i].shx == 4)) {
                if (o[i].shx == 4)
                    snprintf(buf, sizeof buf, "sfxamt:msl:%d", o[i].amt);
                else
                    snprintf(buf, sizeof buf, "sfxamt:lsl:%d", o[i].amt);
                d = buf;
            } else
                d = "sfx";
            break;
        }
        if (k) shape[k++] = ',';
        size_t dl = strlen(d);
        memcpy(shape + k, d, dl);
        k += dl;
    }
    shape[k] = 0;
    for (unsigned t = 0; t < sizeof a64table / sizeof a64table[0]; t++) {
        const a64tent *E = &a64table[t];
        if (strcmp(E->mn, base) || strcmp(E->shape, shape))
            continue;
        /* an immediate the template holds: that one only (tab_immval.py) */
        if (E->imm_fixed) {
            int j = 0;
            while (j < n && o[j].t != A64_O_IMM)
                j++;
            if (j == n || o[j].imm_known != 1 || o[j].imm != E->immval)
                continue;
        }
        uint32_t w = E->tmpl;
        /* map register operands to rd(4:0), rn(9:5), rm(20:16) in order */
        static const int slotlo[3] = { 0, 5, 16 };
        int slot = 0;
        /* each slot's field cleared first: a template can hold its
         * golden's register there (ld1's post-increment register) */
        for (int i = 0; i < n && slot < 3; i++) {
            if (o[i].t == A64_O_REG &&
                !(o[i].kind == RK_V && o[i].vidx >= 0)) {
                w = (w & ~(31u << slotlo[slot])) | (uint32_t)o[i].regn << slotlo[slot];
                slot++;
            } else if (o[i].t == A64_O_MEM) {
                w = (w & ~(31u << slotlo[slot])) | (uint32_t)o[i].basereg << slotlo[slot];
                slot++;
            }
        }
        if (E->idxrm) {
            for (int i = 0; i < n; i++) {
                if (o[i].t == A64_O_REG && o[i].kind == RK_V && o[i].vidx >= 0) {
                    int lg = o[i].vbits == 8 ? 0 : o[i].vbits == 16 ? 1 :
                             o[i].vbits == 32 ? 2 : 3;
                    w |= ((uint32_t)o[i].vidx << (lg + 1) | (1u << lg)) << 16;
                    if (E->imm4dst > 0 && i > 0) { }
                    break;
                }
            }
            /* INS-style destination index: first vec-with-index operand */
            if (E->imm4dst > 0) {
                for (int i = 0; i < n; i++) {
                    if (o[i].t == A64_O_REG && o[i].kind == RK_V && o[i].vidx >= 0) {
                        w |= (uint32_t)o[i].vidx << 11;
                        break;
                    }
                }
            }
        }
        if (E->immask) {
            int64_t v = o[E->immop].imm;
            int64_t fv = v;
            switch (E->imm_xform) {
            case 1: fv = 64 - v; break;
            case 2: fv = 63 - v; break;
            case 3: fv = v * E->imm_scale; break;
            case 4: fv = 128 - v; break;
            case 5: fv = v / E->imm_scale; break;
            case 6: fv = v / E->imm_scale - 1; break;
            }
            w |= ((uint32_t)fv << E->immlo) & E->immask;
        }
        out[0] = (uint8_t)w;
        out[1] = (uint8_t)(w >> 8);
        out[2] = (uint8_t)(w >> 16);
        out[3] = (uint8_t)(w >> 24);
        *outlen = 4;
        (void)c;
        return ASM_OK;
    }
    /* no entry for these operands: -4 if the mnemonic has others (its
     * form, or an immediate its entries do not hold), -3 if none */
    for (unsigned t = 0; t < sizeof a64table / sizeof a64table[0]; t++)
        if (!strcmp(a64table[t].mn, base))
            return -4;
    return -3;
}

